    54→////////////////////////////////////////////////////////////////////////////////////////////////////
    55→// FFT Functions for Field Elements
    56→////////////////////////////////////////////////////////////////////////////////////////////////////
    57→
    58→/**
    59→ * Fast Fourier Transform.
    60→ *
    61→ * Recursively divide and conquer.
    62→ *
    63→ * @param[out]  out             The results, length `n`
    64→ * @param[in]   in              The input data, length `n * stride`
    65→ * @param[in]   stride          The input data stride
    66→ * @param[in]   roots           Roots of unity, length `n * roots_stride`
    67→ * @param[in]   roots_stride    The stride interval among the roots of unity
    68→ * @param[in]   n               Length of the FFT, must be a power of two
    69→ */
    70→static void fr_fft_fast(
    71→    fr_t *out, const fr_t *in, size_t stride, const fr_t *roots, size_t roots_stride, size_t n
    72→) {
    73→    size_t half = n / 2;
    74→    if (half > 0) {
    75→        fr_t y_times_root;
